void HandleReceivedResourceLinks(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (resources_list.size() != referrers_list.size()) {
        return;
    }

    size_t total_items = resources_list.size() + frames_list.size();
    if (is_downloading) {
        download.total_bytes = total_items * AVG_RESOURCE_SIZE;
    }

    for (size_t i = 0; i < resources_list.size(); ++i) {
        if (resources_list[i].is_valid()) {
            SaveItem item;
            item.url = resources_list[i];
            item.referrer = referrers_list[i];
            waiting_queue.push(item);
        }
    }

    for (const GURL& frame_url : frames_list) {
        if (frame_url.is_valid()) {
            SaveItem item;
            item.url = frame_url;
            item.referrer = Referrer();
            waiting_queue.push(item);
        }
    }

    if (waiting_queue.empty()) {
        // Treat as user cancellation
        cancel_download = true;
    }

    update_wait_state(WAITING_FOR_SAVE);
    StartSaving();
}

void HandleReceivingResourceLinks(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
  if (resources_list.size() != referrers_list.size()) {
    return;
  }

  size_t total_items = resources_list.size() + frames_list.size();
  if (download_in_progress) {
    download->total_bytes += total_items;
  }

  for (size_t i = 0; i < resources_list.size(); ++i) {
    const GURL& url = resources_list[i];
    const Referrer& referrer = referrers_list[i];
    if (url.is_valid()) {
      SaveItem item;
      item.url = url;
      item.referrer = referrer;
      waiting_queue.push_back(item);
    }
  }

  for (const GURL& url : frames_list) {
