void handle_savable_resource_links(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (resources_list.size() != referrers_list.size()) {
        // Mismatch in resources and referrers lists; cannot proceed.
        return;
    }

    size_t total_items = resources_list.size() + frames_list.size();
    if (download_in_progress) {
        download.total_bytes += total_items * sizeof(SaveItem);
    }

    for (size_t i = 0; i < resources_list.size(); ++i) {
        GURL resource_url = resources_list[i];
        Referrer referrer = referrers_list[i];

        if (resource_url.is_valid()) {
            SaveItem item;
            item.url = resource_url;
            item.referrer = referrer;
            waiting_queue.push(item);
        }
    }

    for (GURL frame_url : frames_list) {
        if (frame_url.is_valid()) {
            SaveItem item;
            item.url = frame_url;
            waiting_queue.push(item);
        }
    }

    if (waiting_queue.empty()) {
        // No items to save, treat as user cancellation.
        cancel_saving();
        return;
    }

    update_wait_state(WAITING_FOR_SAVING);
    start_saving_process();
}

#include <vector>
#include "GURL.h"
#include "Referrer.h"
#include "SaveItem.h"

void handleResourceReception(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    // Check if it is in the correct wait state
    if (!isInWaitState()) {
        return;
    }

    // Check if the sizes of the resources and referrers lists match
    if (resources_list.size() != referrers_list.size()) {
        return;
    }

    int total_items = resources_list.size() + frames_list.size();
    if (total_items > 0) {
        updateDownloadTotalBytes(total_items * AVG_RESOURCE_SIZE);
    }

    for (size_t i = 0; i < resources_list.size(); ++i) {
        const GURL& url = resources_list[i];
        const Referrer& referrer = referrers_list[i];
        if (!url.is_valid()) {
            continue;
        }

        SaveItem item(url, referrer);
        waiting_queue.push(item);
    }

    for (const GURL& frame_url : frames_list) {
        if (!frame_url.is_valid()) {
            continue;
        }

        SaveItem item(frame_url, Referrer());
        waiting_queue.push(item);
    }

    if (waiting_queue.empty()) {
        handleUserCancellation();
    }

    updateWaitState(false);
    startSavingProcess();
}
